#include <stdio.h>

int main() {
    FILE *file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Could not open file.\n");
        return 1;
    }

    int num;
    fread(&num, sizeof(int), 1, file);
    fclose(file);

    printf("%d\n", num);
    return 0;
}

#include <stdio.h>

int main() {
    FILE *file = fopen("numbers.bin", "rb");
    if (file == NULL) {
        printf("Could not open file.\n");
        return 1;
    }

    int num;
    while (fread(&num, sizeof(int), 1, file)) {
        printf("%d ", num);
    }
    fclose(file);
    return 0;
}

