#include <stdio.h>

int main() {
    FILE *file = fopen("data.bin", "rb");
    if (file == NULL) {
        return 1;
    }

    fseek(file, sizeof(int), SEEK_SET);
    int num;
    fread(&num, sizeof(int), 1, file);

    printf("%d\n", num);
    fclose(file);
    return 0;
}
